// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint64 ts, uint64 bn) public {
        // first accepted call establishes a baseline pastBlockTime
        vm.warp(1000);
        vm.roll(50);
        address actor = address(0xABCD);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call: choose block.timestamp and block.number freely (admissible:
        // timestamp strictly greater than stored pastBlockTime)
        vm.assume(ts > c.pastBlockTime());
        vm.assume(bn >= 1);
        vm.warp(ts);
        vm.roll(bn);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);

        // General rule: after an accepted call, pastBlockTime equals the
        // block.timestamp of that call. The mutant stores block.number instead,
        // which differs from ts for most (ts, bn) pairs.
        assertTrue(c.pastBlockTime() == ts);
    }
}
